// Refresh Screen Buffer (Resoulotion) (run without screen refresh)
void Glue3DSprite::RefreshScreenBuffer(Value resoulotion)
{
    stage.engineScreenChannel = (std::floor(480 * stage.engineRes.Num())) * (std::floor(360 * stage.engineRes.Num()));
    stage.screenRenderer.DeleteAll();
    for (double i1 = 0, times1 = Round(4 * stage.engineScreenChannel.Num()); i1 < times1; i1++)
    {
        stage.screenRenderer.Add(0);
    }
    stage.engineScreenTimestamp = 0;
    stage.engineScreenChannelrow = std::floor(480 * stage.engineRes.Num());
    stage.engineScreenChannelcolumn = std::floor(360 * stage.engineRes.Num());
}

// engine.pixel (x) (y) (z) color (rgb) (brightness) shadow (shadow) (run without screen refresh)
void Glue3DSprite::EnginePixelColorShadow(Value x, Value y, Value z, Value rgb, Value brightness, Value shadow)
{
    stage.engineScreenPixel = 1 + Round((x.Num() + 240) * stage.engineRes.Num()) + (Round((180 - y.Num()) * stage.engineRes.Num()) * stage.engineScreenChannelrow.Num());
    if ((Gt(rgb, 1) && (Lt(std::fabs(x.Num()), 240) && Lt(std::fabs(y.Num()), 180))) && ((Gt(stage.screenRenderer.Item(stage.engineScreenPixel.Num() + stage.engineScreenChannel.Num()), z) && Eq(stage.screenRenderer.Item(stage.engineScreenPixel), stage.engineScreenTimestamp)) || Lt(stage.screenRenderer.Item(stage.engineScreenPixel), stage.engineScreenTimestamp)))
    {
        if (Eq(shadow, 1))
        {
            stage.screenRenderer.Replace(stage.engineScreenPixel, stage.engineScreenTimestamp);
            stage.screenRenderer.Replace(stage.engineScreenPixel.Num() + stage.engineScreenChannel.Num(), z);
            stage.screenRenderer.Replace(stage.engineScreenPixel.Num() + (stage.engineScreenChannel.Num() * 2), 1 + stage.screenRenderer.Item(stage.engineScreenPixel.Num() + (stage.engineScreenChannel.Num() * 2)).Num());
            stage.screenRenderer.Replace(stage.engineScreenPixel.Num() + (stage.engineScreenChannel.Num() * 3), brightness.Num() + stage.engineShadow.Num());
        }
        else
        {
            stage.screenRenderer.Replace(stage.engineScreenPixel, stage.engineScreenTimestamp);
            stage.screenRenderer.Replace(stage.engineScreenPixel.Num() + stage.engineScreenChannel.Num(), z);
            stage.screenRenderer.Replace(stage.engineScreenPixel.Num() + (stage.engineScreenChannel.Num() * 2), rgb);
            stage.screenRenderer.Replace(stage.engineScreenPixel.Num() + (stage.engineScreenChannel.Num() * 3), brightness);
        }
    }
}

