        stage.engineRayx = stage.ramEngineData.Item(112).Num() + (stage.engineRayVectorx1.Num() * stage.engineRaydistance.Num());
        stage.engineRayz = stage.ramEngineData.Item(116).Num() + (stage.engineRayVectorz1.Num() * stage.engineRaydistance.Num());
        stage.engineTile2 = std::floor(stage.engineRayx.Num() + Nz(worldwidth.Num() / 2)) + ((std::floor(stage.engineRayz.Num() + Nz(worldwidth.Num() / 2))) * worldwidth.Num()) + 4;
        stage.engineTile = stage.loadedTileMap.Item(stage.engineTile2.Num() + (2 * (worldwidth.Num() * worldwidth.Num())));
        if ((Eq(stage.engineGhost, 0) && (Gt(stage.engineFirstray, 1) && Gt(stage.engineTile, 0))) && (Lt(std::fabs(stage.engineRayx.Num()), worldwidth.Num() / 2) && Lt(std::fabs(stage.engineRayz.Num()), worldwidth.Num() / 2)))
        {
            stage.engineTiley = stage.loadedTileMap.Item(stage.engineTile2);
            stage.engineTileheight = stage.loadedTileMap.Item(stage.engineTile2.Num() + (1 * (worldwidth.Num() * worldwidth.Num()))).Num() - 1;
            if (Lt(stage.ramEngineData.Item(114).Num() - stage.engineTiley.Num(), -0.5) || Gt(stage.ramEngineData.Item(114).Num() - stage.engineTiley.Num(), 0.5 + stage.engineTileheight.Num()))
            {
                if (Gt(stage.ramEngineData.Item(114), stage.engineTiley.Num() + (stage.engineTileheight.Num() + 0)))
                {
                    stage.engineY1 = (0.5 + stage.engineTileheight.Num() + (stage.engineTiley.Num() - stage.ramEngineData.Item(114).Num())) / stage.engineRaydistance.Num();
                }
                else
                {
                    stage.engineY1 = (-0.5 + (stage.engineTiley.Num() - stage.ramEngineData.Item(114).Num())) / stage.engineRaydistance.Num();
                }
                Engine2draycastverticalTextureBrightnessGhostMode7HeightAo(stage.engineDrawx, stage.engineRaydistance, -3 * stage.ramEngineData.Item(120).Num() + stage.engineY1.Num(), stage.engineY2.Num() - Nz((0.025 * (-1 + (Num(Gt(stage.ramEngineData.Item(114), stage.engineTiley.Num() + (stage.engineTileheight.Num() + 0))) * 2))) / stage.engineRaydistance.Num()), stage.enginePrevtile, stage.engineTiley, Value(Gt(stage.ramEngineData.Item(114), stage.engineTiley.Num() + (stage.engineTileheight.Num() + 0))), -10 + (Num(Gt(stage.ramEngineData.Item(114), stage.engineTiley.Num() + (stage.engineTileheight.Num() + 0))) * 15), 0, 1, stage.engineTileheight, u""_s, u""_s);
            }
        }
        stage.engineRaydistance = stage.engineRaydistance.Num() + (2e-09);
        stage.engineRayx = stage.ramEngineData.Item(112).Num() + (stage.engineRayVectorx1.Num() * stage.engineRaydistance.Num());
        stage.engineRayz = stage.ramEngineData.Item(116).Num() + (stage.engineRayVectorz1.Num() * stage.engineRaydistance.Num());
        stage.engineTile2 = std::floor(stage.engineRayx.Num() + Nz(worldwidth.Num() / 2)) + ((std::floor(stage.engineRayz.Num() + Nz(worldwidth.Num() / 2))) * worldwidth.Num()) + 4;
        stage.engineTile = stage.loadedTileMap.Item(stage.engineTile2.Num() + (2 * (worldwidth.Num() * worldwidth.Num())));
