// engine.loadmodel (DataName) (run without screen refresh)
void Glue3DSprite::EngineLoadmodel(Value dataName)
{
    FileFindData(dataName);
    stage.guiInteract = 2;
    if (Eq(stage.fileFound, 1))
    {
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 1, u""_s, u""_s, u""_s);
        if (Eq(stage.decodedElements.Item(2), u"tile"_s))
        {
            stage.loadedTileMap.DeleteAll();
            stage.fileDat = stage.engineFiles.Item(stage.fileLoadIndex);
            stage.proccessDecode = u""_s;
            stage.proccessDecodeIndex = 1;
            for (double i1 = 0, times1 = Round(stage.fileDat.Str().Length()); i1 < times1; i1++)
            {
                stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), stage.fileDat.Str());
                if (Eq(LetterOf(stage.proccessDecodeIndex.Num() + 1, stage.fileDat.Str()), u"|"_s))
                {
                    stage.loadedTileMap.Add(stage.proccessDecode);
                    stage.proccessDecode = u""_s;
                    stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
                }
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
            }
            stage.loadedTileMap.Replace(1, dataName);
            stage.loadedTileMap.Insert(2, stage.loadedTileMap.Item(2));
        }
        else if (Eq(stage.decodedElements.Item(2), u"mode7"_s))
        {
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 2, u""_s, u""_s, u""_s);
            stage.engineMode7texture = stage.decodedElements.Item(3);
        }
        else if (Eq(stage.decodedElements.Item(2), u"segment"_s))
        {
            stage.loadedPolygonMap.DeleteAll();
            stage.fileDat = stage.engineFiles.Item(stage.fileLoadIndex);
            stage.proccessDecode = u""_s;
            stage.proccessDecodeIndex = 1;
            for (double i1 = 0, times1 = Round(stage.fileDat.Str().Length()); i1 < times1; i1++)
            {
                stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), stage.fileDat.Str());
                if (Eq(LetterOf(stage.proccessDecodeIndex.Num() + 1, stage.fileDat.Str()), u"|"_s))
                {
                    stage.loadedPolygonMap.Add(stage.proccessDecode);
                    stage.proccessDecode = u""_s;
                    stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
                }
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
            }
            stage.loadedPolygonMap.Replace(1, dataName);
        }
        else if (Eq(stage.editorTab, u"model"_s))
        {
            stage.loadedModels.DeleteAll();
            stage.loadedModels.Add(0);
            EngineLoad3dModelBone(dataName, u""_s, u""_s);
        }
        else
        {
            EngineLoad3dModelBone(dataName, u""_s, u""_s);
        }
    }
}

