// File.FindData (DataName) (run without screen refresh)
void Glue3DSprite::FileFindData(Value dataName)
{
    stage.fileLoadIndex = 0;
    stage.fileFound = 0;
    for (double i1 = 0, times1 = Round(stage.engineFiles.Length()); i1 < times1; i1++)
    {
        stage.fileLoadIndex = stage.fileLoadIndex.Num() + 1;
        if (Contains(stage.engineFiles.Item(stage.fileLoadIndex).Str(), u","_s))
        {
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 0, u","_s, u""_s, u""_s);
            if (Eq(stage.decodedElements.Item(1), dataName))
            {
                stage.fileFound = 1;
                stage.fileFolderIndex = stage.fileLoadIndex;
                for (double i2 = 0, times2 = Round(10000); i2 < times2; i2++)
                {
                    stage.fileFolderIndex = stage.fileFolderIndex.Num() + -1;
                    if (!Eq(Num(stage.engineFiles.Item(stage.fileFolderIndex.Num() + 1).Str() + u""_s) - 123456789, -123456789))
                    {
                        stage.fileFilename = stage.engineFiles.Item(stage.fileFolderIndex);
                        return;
                    }
                }
                return;
            }
        }
    }
    stage.fileLoadIndex = 0;
}

// engine.free_camera (speed) (turn) (run without screen refresh)
void Glue3DSprite::EngineFreeCamera(Value speed, Value turn)
{
    CreateAddress(u"engine.camera_direction_z"_s, 0, 61);
    if ((Eq(stage.editorModelType, u"3d"_s) && Eq(stage.loadedModels.Item(4), u"billboard"_s)) && Eq(stage.editorTab, u"model"_s))
    {
        CreateAddress(u"engine.camera_direction_x"_s, 0, 59);
    }
    else
    {
        // EDITED: hold the right mouse button and drag to turn (was: left/right arrow keys).
        CreateAddress(u"engine.camera_direction_x"_s, MouseLookX() + stage.ramEngineData.Item(118).Num(), 59);
    }
    // EDITED: drag up/down with the right mouse button to look up/down (was: up/down arrow keys).
    CreateAddress(u"engine.camera_direction_y"_s, MouseLookY() + stage.ramEngineData.Item(120).Num(), 60);
    if (Eq(1, 0))
    {
        CreateAddress(u"engine.camera_direction_x"_s, MouseX(), 59);
        CreateAddress(u"engine.camera_direction_y"_s, MouseY() / 2, 60);
    }
    // EDITED: up/down limit is MaxCameraPitch (90, like Unity) instead of 45.
    if (Gt(stage.ramEngineData.Item(120), MaxCameraPitch))
    {
        CreateAddress(u"engine.camera_direction_y"_s, MaxCameraPitch, 60);
    }
    if (Lt(stage.ramEngineData.Item(120), -MaxCameraPitch))
    {
        CreateAddress(u"engine.camera_direction_y"_s, -MaxCameraPitch, 60);
    }
    CreateAddress(u"engine.camera_x"_s, (Nz(Sin(90 + stage.ramEngineData.Item(118).Num())) * (Num(KeyPressed(u"d"_s)) - Num(KeyPressed(u"a"_s)))) * speed.Num() + stage.ramEngineData.Item(112).Num(), 56);
    CreateAddress(u"engine.camera_z"_s, (Nz(Cos(90 + stage.ramEngineData.Item(118).Num())) * (Num(KeyPressed(u"d"_s)) - Num(KeyPressed(u"a"_s)))) * speed.Num() + stage.ramEngineData.Item(116).Num(), 58);
    if (KeyPressed(u"space"_s) && KeyPressed(u"`"_s))
    {
        CreateAddress(u"engine.camera_y"_s, 0, 57);
    }
    else
    {
        CreateAddress(u"engine.camera_y"_s, (Num(KeyPressed(u"space"_s)) - Num(KeyPressed(u"shift"_s + u""_s))) * speed.Num() + stage.ramEngineData.Item(114).Num(), 57);
        if (Lt(stage.ramEngineData.Item(114), -0.25))
        {
            CreateAddress(u"engine.camera_y"_s, -0.25, 57);
        }
    }
    CreateAddress(u"engine.camera_x"_s, (Nz(Sin(stage.ramEngineData.Item(118).Num())) * (Num(KeyPressed(u"w"_s)) - Num(KeyPressed(u"s"_s)))) * speed.Num() + stage.ramEngineData.Item(112).Num(), 56);
    CreateAddress(u"engine.camera_z"_s, (Nz(Cos(stage.ramEngineData.Item(118).Num())) * (Num(KeyPressed(u"w"_s)) - Num(KeyPressed(u"s"_s)))) * speed.Num() + stage.ramEngineData.Item(116).Num(), 58);
    if (KeyPressed(u"h"_s))
    {
        CreateAddress(u"engine.camera_x"_s, 0, 56);
        CreateAddress(u"engine.camera_y"_s, 0, 57);
        CreateAddress(u"engine.camera_z"_s, 0, 58);
        CreateAddress(u"engine.camera_direction_x"_s, 0.01, 59);
        CreateAddress(u"engine.camera_direction_y"_s, 0, 60);
        CreateAddress(u"engine.camera_direction_z"_s, 0, 61);
    }
    // EDITED: mouse wheel zoom, middle-button pan, Q/E up/down while right-dragging (Custom/CameraControls.cpp).
    UnityStyleCameraExtras(speed);
}

