                EnginePixelColorShadow(x, stage.engineFillY, z, stage.loadedTextures.Item(1 + (std::floor(Nz(Mod(stage.engineMode7rayx.Num() * 32, 32)))) + ((std::floor(Nz(Mod(stage.engineMode7rayz.Num() * 32, 32)))) * 32 + ((texture.Num() - 1) * 1024))), b, u""_s);
                stage.engineFillY = stage.engineFillY.Num() + stage.engineFillStepy.Num();
