                stage.engineMode7rayx = stage.ramEngineData.Item(112).Num() + ((stage.engineRayMode7vecx1.Num() + ((stage.engineRayMode7vecx2.Num() - stage.engineRayMode7vecx1.Num()) * Nz((x.Num() + 240) / 480))) * stage.engineRayMagnitude.Num());
                stage.engineMode7rayz = stage.ramEngineData.Item(116).Num() + ((stage.engineRayMode7vecy1.Num() + ((stage.engineRayMode7vecy2.Num() - stage.engineRayMode7vecy1.Num()) * Nz((x.Num() + 240) / 480))) * stage.engineRayMagnitude.Num());
                EnginePixelColorShadow(x, stage.engineFillY, z, stage.loadedTextures.Item(1 + (std::floor(Nz(Mod(stage.engineMode7rayx.Num() * 32, 32)))) + ((std::floor(Nz(Mod(stage.engineMode7rayz.Num() * 32, 32)))) * 32 + ((texture.Num() - 1) * 1024))), b, u""_s);
                stage.engineFillY = stage.engineFillY.Num() + stage.engineFillStepy.Num();
