                EnginePixelColorShadow(x, stage.engineFillY, z, stage.engineTextures.Item(1 + (std::floor(Nz(Mod((stage.engineRayx.Num() + stage.engineRayz.Num()) * 50, 50)))) + ((std::floor(Nz(Mod((Nz((y1.Num() - stage.engineFillY.Num()) / (std::fabs(y2.Num() - y1.Num()))) * 50) * v.Num(), 50)))) * 50 + 2500)), b, u""_s);
