// engine.3Dskybox (run without screen refresh)
void Glue3DSprite::Engine3Dskybox()
{
    SetPenSize(625);
    SetPenColor(u"#98c8ff"_s);
    GoTo(0, 0);
    stage.engine3DskyboxRes = 0.25;
    PenDown();
    PenUp();
    SetEffect(Effect::Pixelate, 76);
    Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_engine.sun"_s, 480 * Nz(Nz(Mod(stage.ramEngineData.Item(118).Num() * -1.5, 360)) / 360) - 240 + stage.engineScreenMidx.Num(), stage.engineScreenMidy.Num() + 35 + (-1.5 * stage.ramEngineData.Item(120).Num()), 90, 40 * stage.engineSkyboxScale.Num(), 25, 15, 0, u""_s, u""_s, u""_s, u""_s, u""_s);
    ClearEffects();
    SetPenSize(Nz(1.5 / stage.engine3DskyboxRes.Num()));
    stage.engineStepx = Nz((stage.engineScreenBottomrightx.Num() - stage.engineScreenTopleftx.Num()) / 480) / stage.engine3DskyboxRes.Num();
    stage.engineStepy = Nz(stage.engineScreenToplefty.Num() / 180) / stage.engine3DskyboxRes.Num();
    stage.engineRayVectorx1 = Nz(Sin(stage.ramEngineData.Item(118).Num() + 90)) * -240 - (Nz(Cos(stage.ramEngineData.Item(118).Num() + 90)) * stage.engineFov.Num());
    stage.engineRayVectorz1 = Nz(Cos(stage.ramEngineData.Item(118).Num() + 90)) * -240 + (Nz(Sin(stage.ramEngineData.Item(118).Num() + 90)) * stage.engineFov.Num());
    stage.engineRayVectorx2 = Nz(Sin(stage.ramEngineData.Item(118).Num() + 90)) * 240 - (Nz(Cos(stage.ramEngineData.Item(118).Num() + 90)) * stage.engineFov.Num());
    stage.engineRayVectorz2 = Nz(Cos(stage.ramEngineData.Item(118).Num() + 90)) * 240 + (Nz(Sin(stage.ramEngineData.Item(118).Num() + 90)) * stage.engineFov.Num());
    stage.engineDrawy = 0;
    for (double i1 = 0, times1 = Round((195 - (-2.1 * stage.ramEngineData.Item(120).Num())) * stage.engine3DskyboxRes.Num()); i1 < times1; i1++)
    {
        stage.engineRayMagnitude = 180 / stage.engineDrawy.Num();
        stage.engineRayStepx = Nz((stage.engineRayVectorx2.Num() - stage.engineRayVectorx1.Num()) / (480 * stage.engine3DskyboxRes.Num())) * stage.engineRayMagnitude.Num();
        stage.engineRayStepz = Nz((stage.engineRayVectorz2.Num() - stage.engineRayVectorz1.Num()) / (480 * stage.engine3DskyboxRes.Num())) * stage.engineRayMagnitude.Num();
        stage.engineRayx = stage.ramEngineData.Item(112).Num() * 25 + (stage.engineRayVectorx1.Num() * stage.engineRayMagnitude.Num());
        stage.engineRayz = stage.ramEngineData.Item(116).Num() * 25 + (stage.engineRayVectorz1.Num() * stage.engineRayMagnitude.Num());
        stage.engineDrawx = stage.engineScreenTopleftx;
        for (double i2 = 0, times2 = Round(480 * stage.engine3DskyboxRes.Num()); i2 < times2; i2++)
        {
            GoTo(stage.engineDrawx.Num(), -1.5 * stage.ramEngineData.Item(120).Num() + stage.engineDrawy.Num() + Nz((17 * (stage.trigonometry.Item(Nz(Mod((stage.engineRayx.Num() * 0.25 + (Timer() * 5)) * 1, 360)) + 1).Num() * 0.5 + (stage.trigonometry.Item(Nz(Mod((stage.engineRayz.Num() * 0.25 + (Timer() * 5)) * 1.105, 360)) + 361).Num() * 1))) / stage.engineRayMagnitude.Num()));
            stage.enginePixel = stage.engineTextures.Item(std::floor(Nz(Mod(stage.engineRayx.Num() * 0.06 + (Timer() * 5), 50))) + ((std::floor(Nz(Mod(stage.engineRayz.Num() * 0.06 + (Timer() * 5), 50)))) * 50 + 1) + 0);
            SetPenColor(stage.enginePixel);
            SetPenParam(PenParam::Transparency, Num(Gt(stage.enginePixel, 9000000)) * 15 + (100 - stage.engineDrawy.Num()));
            PenDown();
            PenUp();
            stage.engineRayx = stage.engineRayx.Num() + stage.engineRayStepx.Num();
            stage.engineRayz = stage.engineRayz.Num() + stage.engineRayStepz.Num();
            stage.engineDrawx = stage.engineDrawx.Num() + stage.engineStepx.Num();
        }
        stage.engineDrawy = stage.engineDrawy.Num() + stage.engineStepy.Num();
    }
}

