            Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.selector"_s, (stage.elementData.Item(1).Num() + stage.elementData.Item(3).Num()) / 2, stage.renderDrawY, 90, 40, 90, 0, 0, 1, 1, u""_s, 1, u""_s);
